write_file({"relative_path":"workspace/extract_labels.py","content":"import json, ast
nb_path = 'notebooks/adv_tutorial.ipynb'
with open(nb_path, 'r', encoding='utf-8') as f:
    nb = json.load(f)
labels = None
for cell in nb.get('cells', []):
    if cell.get('cell_type') == 'code':
        src = ''.join(cell.get('source', []))
        if 'author_labels' in src and '=' in src:
            # find the assignment line
            for line in src.splitlines():
                if line.strip().startswith('author_labels') and '=' in line:
                    rhs = line.split('=',1)[1].strip()
                    try:
                        labels = ast.literal_eval(rhs)
                    except Exception:
                        # try to evaluate by exec in restricted dict
                        loc = {}
                        exec(line, {}, loc)
                        labels = loc.get('author_labels')
                    break
    if labels is not None:
        break
if labels is None:
    print('NO_LABELS_FOUND')
else:
    unique = sorted(set(labels))
    print(len(unique))
    print(labels)
"})
